class Solution {
public:
    int getPower(int x) {
        int steps = 0;
        while (x != 1) {
            if (x % 2 == 0) x /= 2;
            else x = 3 * x + 1;
            steps++;
        }
        return steps;
    }
    int getKth(int lo, int hi, int k) {
        vector<pair<int,int>> v;
        for (int x = lo; x <= hi; x++)
            v.push_back({getPower(x), x});
        sort(v.begin(), v.end());
        return v[k - 1].second;
    }
};

