class Solution {
    private int getPower(int x) {
        int steps = 0;
        while (x != 1) {
            if (x % 2 == 0) x /= 2;
            else x = 3 * x + 1;
            steps++;
        }
        return steps;
    }
    public int getKth(int lo, int hi, int k) {
        List<int[]> list = new ArrayList<>();
        for (int x = lo; x <= hi; x++)
            list.add(new int[]{getPower(x), x});
        list.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        return list.get(k - 1)[1];
    }
}

