var getKth = function(lo, hi, k) {
    const memo = new Map([[1, 0]]);
    const power = (x) => {
        if (memo.has(x)) return memo.get(x);
        const next = x % 2 === 0 ? x / 2 : 3 * x + 1;
        const res = 1 + power(next);
        memo.set(x, res);
        return res;
    };
    const arr = [];
    for (let x = lo; x <= hi; x++) arr.push([power(x), x]);
    arr.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
    return arr[k - 1][1];
};
